ep_transform.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "system").trim();
if (actor == "") {
  actor = "system";
}
let dryRun = body.dryRun == true || req.dryRun == true;
let eventId = str(body.eventId ?? req.eventId ?? "").trim();

let events = vdb.collection("inbound_events");
let rows = [];
if (eventId != "") {
  let lookup = events.find({eventId: {$eq: eventId}}, 1);
  rows = lookup.data ?? [];
}
if (leng(rows) == 0) {
  let fallback = events.find({}, 1);
  rows = fallback.data ?? [];
}
if (leng(rows) == 0) {
  return {ok: false, statusCode: 404, reason: "No inbound event is available to transform"};
}

let eventDoc = rows[0];
eventId = str(eventDoc.eventId ?? eventId).trim();
let source = str(eventDoc.source ?? "").trim();
let payload = type(eventDoc.payload) == "object" ? eventDoc.payload : {};
let nowTs = datetime.now().isoformat();
let transformedPayload = {
  original: payload,
  normalizedSource: source.lower(),
  transformedAt: nowTs,
  transformedBy: actor,
  eventId: eventId
};

if (dryRun) {
  return {ok: true, dryRun: true, eventId: eventId, source: source, transformed: transformedPayload};
}

let updateRes = events.update({eventId: {$eq: eventId}}, {payload: transformedPayload});
if (updateRes.ok == false) {
  return {ok: false, statusCode: 500, reason: updateRes.error ?? "Failed to persist transformed event", eventId: eventId, result: updateRes};
}

let runs = vdb.collection("event_transform_runs");
let runId = crypto.uuid();
let runRes = runs.insert({
  runId: runId,
  eventId: eventId,
  source: source,
  transformedAt: nowTs,
  transformedBy: actor,
  payload: transformedPayload
});

return {ok: true, eventId: eventId, runId: runId, transformedAt: nowTs, updated: true, runRecorded: runRes.ok ?? false, transformed: transformedPayload};

