ep_dispatch.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "system").trim();
if (actor == "") {
  actor = "system";
}
let dryRun = body.dryRun == true || req.dryRun == true;
let eventId = str(body.eventId ?? req.eventId ?? "").trim();

let events = vdb.collection("inbound_events");
let rows = [];
if (eventId != "") {
  let lookup = events.find({eventId: {$eq: eventId}}, 1);
  rows = lookup.data ?? [];
}
if (leng(rows) == 0) {
  let fallback = events.find({}, 1);
  rows = fallback.data ?? [];
}
if (leng(rows) == 0) {
  return {ok: false, statusCode: 404, reason: "No inbound event is available to dispatch"};
}

let eventDoc = rows[0];
eventId = str(eventDoc.eventId ?? eventId).trim();
let source = str(eventDoc.source ?? "").trim();
let payload = type(eventDoc.payload) == "object" ? eventDoc.payload : {};
let target = str(body.target ?? req.target ?? payload.target ?? "").trim();
if (target == "") {
  target = "internal://" + (source == "" ? "unknown-source" : source);
}

let nowTs = datetime.now().isoformat();
let jobId = crypto.uuid();
let job = {
  jobId: jobId,
  eventId: eventId,
  source: source,
  target: target,
  status: "QUEUED",
  queuedAt: nowTs,
  queuedBy: actor,
  payload: payload
};

if (dryRun) {
  return {ok: true, dryRun: true, eventId: eventId, target: target, job: job};
}

let queue = vdb.collection("event_dispatch_jobs");
let queueRes = queue.insert(job);
if (queueRes.ok == false) {
  return {ok: false, statusCode: 500, reason: queueRes.error ?? "Failed to queue dispatch job", eventId: eventId, jobId: jobId, result: queueRes};
}

let nextPayload = {
  original: payload.original ?? payload,
  normalizedSource: str(payload.normalizedSource ?? source.lower()).trim(),
  dispatch: {
    target: target,
    status: "QUEUED",
    queuedAt: nowTs,
    queuedBy: actor,
    jobId: jobId
  }
};
let updateRes = events.update({eventId: {$eq: eventId}}, {payload: nextPayload});

return {ok: true, eventId: eventId, jobId: jobId, target: target, queuedAt: nowTs, queued: true, updated: updateRes.ok ?? false};

